package com.bn.aliagent.evaluation.candidate;
public final class CandidateReviewService { private final CandidateRepository repo; public CandidateReviewService(CandidateRepository r){repo=r;} public void save(EvaluationCandidate c){repo.save(c);} public EvaluationCandidate review(CandidateReviewCommand c){var v=repo.require(c.tenantId(),c.candidateId()); if(v.status()!=CandidateStatus.PENDING_REVIEW)throw new IllegalStateException("候选不可审核"); if(c.action()==ReviewAction.ACCEPT&&(c.expected()==null||c.expected().isEmpty()||c.labels()==null||c.labels().isEmpty()))throw new IllegalArgumentException("接受必须包含期望结果和标签"); var n=new EvaluationCandidate(v.id(),v.tenantId(),c.action()==ReviewAction.ACCEPT?CandidateStatus.ACCEPTED:CandidateStatus.REJECTED,v.body(),v.digest(),v.createdAt(),c.expected()==null?java.util.Map.of():c.expected(),c.labels()==null?java.util.Set.of():c.labels(),c.reason());repo.save(n);return n;} }
